-- Structure for BASE TABLE `mikrotik_devices`
-- ----------------------------
DROP BASE TABLE IF EXISTS `mikrotik_devices`;
CREATE TABLE `mikrotik_devices` (
  `id` int NOT NULL AUTO_INCREMENT,
  `device_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `ip_address` varchar(45) NOT NULL,
  `api_username` varchar(50) NOT NULL,
  `api_password` varchar(50) NOT NULL,
  `api_port` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

