-- Structure for BASE TABLE `napbox_mapping`
-- ----------------------------
DROP BASE TABLE IF EXISTS `napbox_mapping`;
CREATE TABLE `napbox_mapping` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `napbox_no` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `marker_color` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `lcp_no` varchar(50) DEFAULT NULL,
  `nap_no` varchar(50) DEFAULT NULL,
  `splitter_no` enum('1x2','1x4','1x8','1x16') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `port_no` varchar(50) DEFAULT NULL,
  `client_username` varchar(100) DEFAULT NULL,
  `nap_latitude` decimal(9,6) DEFAULT NULL,
  `nap_longitude` decimal(9,6) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `customer_id` int NOT NULL,
