-- ----------------------------
-- Structure for BASE TABLE `payments`
-- ----------------------------
DROP BASE TABLE IF EXISTS `payments`;
CREATE TABLE `payments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(255) NOT NULL,
  `plan_name` varchar(255) NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `days` int NOT NULL,
  `expires_at` datetime DEFAULT NULL,
  `paid_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `adjusted_by` varchar(100) DEFAULT NULL,
  `payment_method` enum('cash','bank_transfer','e-wallet','payment_center','online_banking') DEFAULT NULL,
  `reference_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `payment_date_received` datetime NOT NULL,
  `reason` varchar(255) DEFAULT NULL,
  `start_date` datetime DEFAULT NULL,
  `mikrotik_devices` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_reference_no` (`reference_no`)
) ENGINE=MyISAM AUTO_INCREMENT=1182 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

