-- ----------------------------
-- Structure for BASE TABLE `rebates`
-- ----------------------------
DROP BASE TABLE IF EXISTS `rebates`;
CREATE TABLE `rebates` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(100) NOT NULL,
  `plan_name` varchar(100) NOT NULL,
  `days` int DEFAULT '0',
  `expires_at` datetime DEFAULT NULL,
  `paid_at` datetime DEFAULT NULL,
  `adjusted_by` varchar(100) DEFAULT NULL,
  `note` text,
  `mikrotik_devices` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `current_expiry` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=648 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

